import { useState, useEffect } from "react";
import axios from "axios";

function App() {

  const [message, setMessage] = useState("");

  const [conversations, setConversations] = useState([]);

  const [currentChatId, setCurrentChatId] = useState(null);

  const [loading, setLoading] = useState(false);

  /* LOAD SAVED CHATS */

  useEffect(() => {

    const savedChats = localStorage.getItem("conversations");

    if (savedChats) {

      const parsedChats = JSON.parse(savedChats);

      setConversations(parsedChats);

      if (parsedChats.length > 0) {

        setCurrentChatId(parsedChats[0].id);
      }
    }

  }, []);

  /* SAVE CHATS */

  useEffect(() => {

    localStorage.setItem(
      "conversations",
      JSON.stringify(conversations)
    );

  }, [conversations]);

  /* CREATE NEW CHAT */

  const createNewChat = () => {

    const newChat = {
      id: Date.now(),
      title: "New Chat",
      messages: []
    };

    const updatedChats = [
      newChat,
      ...conversations
    ];

    setConversations(updatedChats);

    setCurrentChatId(newChat.id);

    localStorage.setItem(
      "conversations",
      JSON.stringify(updatedChats)
    );
  };

  /* GET CURRENT CHAT */

  const currentChat = conversations.find(
    (chat) => chat.id === currentChatId
  );

  /* SEND MESSAGE */

  const sendMessage = async () => {

    if (!message.trim()) return;

    let activeChatId = currentChatId;

    let updatedConversations = [...conversations];

    /* CREATE CHAT IF NONE EXISTS */

    if (!activeChatId) {

      const newChat = {
        id: Date.now(),
        title: message,
        messages: []
      };

      updatedConversations = [
        newChat,
        ...updatedConversations
      ];

      activeChatId = newChat.id;

      setCurrentChatId(activeChatId);
    }

    /* USER MESSAGE */

    const userMessage = {
      role: "user",
      text: message
    };

    updatedConversations =
      updatedConversations.map((chat) => {

        if (chat.id === activeChatId) {

          return {
            ...chat,

            title:
              chat.messages.length === 0
                ? message
                : chat.title,

            messages: [
              ...chat.messages,
              userMessage
            ]
          };
        }

        return chat;
      });

    setConversations(updatedConversations);

    localStorage.setItem(
      "conversations",
      JSON.stringify(updatedConversations)
    );

    setLoading(true);

    try {

      const res = await axios.post(
        "http://127.0.0.1:8000/api/chat",
        {
          message: message
        }
      );

      const aiMessage = {
        role: "ai",
        text: res.data.response
      };

      const finalConversations =
        updatedConversations.map((chat) => {

          if (chat.id === activeChatId) {

            return {
              ...chat,
              messages: [
                ...chat.messages,
                aiMessage
              ]
            };
          }

          return chat;
        });

      setConversations(finalConversations);

      localStorage.setItem(
        "conversations",
        JSON.stringify(finalConversations)
      );

    } catch (error) {

      console.log(error);

      const errorMessage = {
        role: "ai",
        text: "Backend connection error"
      };

      const errorConversations =
        updatedConversations.map((chat) => {

          if (chat.id === activeChatId) {

            return {
              ...chat,
              messages: [
                ...chat.messages,
                errorMessage
              ]
            };
          }

          return chat;
        });

      setConversations(errorConversations);

      localStorage.setItem(
        "conversations",
        JSON.stringify(errorConversations)
      );
    }

    setMessage("");

    setLoading(false);
  };

  /* DELETE CHAT */

  const deleteChat = (id) => {

    const filteredChats =
      conversations.filter(
        (chat) => chat.id !== id
      );

    setConversations(filteredChats);

    localStorage.setItem(
      "conversations",
      JSON.stringify(filteredChats)
    );

    if (filteredChats.length > 0) {

      setCurrentChatId(filteredChats[0].id);

    } else {

      setCurrentChatId(null);
    }
  };

  return (

    <div className="flex h-screen bg-slate-950 text-white">

      {/* SIDEBAR */}

      <div className="w-72 bg-slate-900 border-r border-slate-800 p-5 flex flex-col">

        <h1 className="text-2xl font-bold text-cyan-400 mb-8">
          AI College Companion
        </h1>

        <button
          onClick={createNewChat}
          className="w-full bg-cyan-500 hover:bg-cyan-600 p-3 rounded-xl font-semibold"
        >
          + New Chat
        </button>

        {/* CHAT LIST */}

        <div className="mt-8 overflow-y-auto space-y-3">

          {
            conversations.map((chat) => (

              <div
                key={chat.id}
                className={`p-3 rounded-lg cursor-pointer flex justify-between items-center ${
                  currentChatId === chat.id
                    ? "bg-cyan-500"
                    : "bg-slate-800 hover:bg-slate-700"
                }`}
              >

                <div
                  className="truncate flex-1"
                  onClick={() =>
                    setCurrentChatId(chat.id)
                  }
                >
                  {chat.title}
                </div>

                <button
                  onClick={() =>
                    deleteChat(chat.id)
                  }
                  className="ml-3 text-red-300 hover:text-red-500"
                >
                  ✕
                </button>

              </div>

            ))
          }

        </div>

      </div>

      {/* MAIN CHAT */}

      <div className="flex-1 flex flex-col">

        {/* HEADER */}

        <div className="p-5 border-b border-slate-800 text-2xl font-semibold text-cyan-300">
          AI Assistant
        </div>

        {/* MESSAGES */}

        <div className="flex-1 overflow-y-auto p-6 space-y-5">

          {
            currentChat?.messages.map(
              (chat, index) => (

                <div
                  key={index}
                  className={`max-w-3xl p-4 rounded-2xl whitespace-pre-wrap leading-7 ${
                    chat.role === "user"
                      ? "bg-cyan-500 ml-auto"
                      : "bg-slate-800"
                  }`}
                >

                  {chat.text}

                </div>

              ))
          }

          {
            loading && (

              <div className="bg-slate-800 p-4 rounded-2xl w-fit animate-pulse">
                AI is thinking...
              </div>

            )
          }

        </div>

        {/* INPUT */}

        <div className="p-5 border-t border-slate-800 flex gap-4">

          <input
            type="text"
            placeholder="Ask anything..."
            value={message}
            onChange={(e) =>
              setMessage(e.target.value)
            }
            onKeyDown={(e) => {

              if (e.key === "Enter") {

                sendMessage();
              }
            }}
            className="flex-1 p-4 rounded-xl bg-slate-800 border border-slate-700 focus:outline-none"
          />

          <button
            onClick={sendMessage}
            className="bg-cyan-500 hover:bg-cyan-600 px-6 rounded-xl font-semibold"
          >
            Send
          </button>

        </div>

      </div>

    </div>
  );
}

export default App;
